/// <summary>
/// Contract for Resourcestatistic
/// </summary>
[DataContractAttribute,
SysOperationGroupAttribute('Group1', "@NDX:NDXResourcesStatisticSource", '1'),
SysOperationGroupAttribute('Group2', "@NDX:NDXResourcesStatisticFilter", '2'),
SysOperationGroupAttribute('Group3', "@NDX:NDXResourcesStatisticDayRange", '3')]
public final class NDXResourcesStatisticContract implements SysOperationInitializable
{
    NoYes fromJob;
    NoYes fromBDE;
    NoYes fromJournal;

    ProdId prodId;
    ItemId itemId;

    date fromDate;
    date toDate;

    ResResourceType resResourceType;

}

Method.Source:
[DataMemberAttribute("fromJob"), SysOperationGroupMemberAttribute('Group1'), SysOperationLabelAttribute("@NDX:NDXResourcesStatisticCollectDataFromJob")]
public NoYes parmFromJob(NoYes _fromJob = fromJob)
{
    fromJob = _fromJob;
    return fromJob;
}

[DataMemberAttribute("fromBDE"), SysOperationGroupMemberAttribute('Group1'), SysOperationLabelAttribute("@NDX:NDXResourcesStatisticCollectDataFromBDE")]
public NoYes parmFromBDE(NoYes _fromBDE = fromBDE)
{
    fromBDE = _fromBDE;
    return fromBDE;
}

[DataMemberAttribute("fromJournal"), SysOperationGroupMemberAttribute('Group1'), SysOperationLabelAttribute("@NDX:NDXResourcesStatisticCollectDataFromJournal")]
public NoYes parmFromJournal(NoYes _fromJournal = fromJournal)
{
    fromJournal = _fromJournal;
    return fromJournal;

}

[DataMemberAttribute("prodId"), SysOperationGroupMemberAttribute('Group2'), SysOperationDisplayOrderAttribute('1')]
public ProdId parmProdId(ProdId _prodId = prodId)
{
    prodId = _prodId;
    return prodId;
}

[DataMemberAttribute("fromJournal"), SysOperationGroupMemberAttribute('Group2'), SysOperationDisplayOrderAttribute('2')]
public ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;
    return itemId;
}

[DataMemberAttribute("fromDate"), SysOperationGroupMemberAttribute('Group3'), SysOperationDisplayOrderAttribute('1'), SysOperationLabelAttribute("@NDX:NDXTo")]
public Date parmFromDate(Date _fromDate = fromDate)
{
    fromDate = _fromDate;
    return fromDate;
}

[DataMemberAttribute("toDate"), SysOperationGroupMemberAttribute('Group3'), SysOperationDisplayOrderAttribute('2'), SysOperationLabelAttribute("@NDX:NDXFrom")]
public Date parmToDate(Date _toDate = toDate)
{
    toDate = _toDate;
    return toDate;
}

public ResResourceType parmResourceType(ResResourceType  _resResourceType = resResourceType)
{
    resResourceType = _resResourceType;
    return resResourceType;
}

public void initialize()
{
    fromJob = false;
    fromBDE = false;
    fromJournal = false;
    resResourceType = ResResourceType::Machine;
}
